Reproduced on Windows with the following harness:
```c++
#include <crtdbg.h>
#include <util/subprocess.h>

std::string SysErrorString(int) { return ""; }

int main()
{
    _CrtSetDbgFlag(_CRTDBG_ALLOC_MEM_DF | _CRTDBG_LEAK_CHECK_DF);
    _CrtSetReportMode(_CRT_WARN, _CRTDBG_MODE_FILE);
    _CrtSetReportFile(_CRT_WARN, _CRTDBG_FILE_STDOUT);

    subprocess::Popen p({"cmd.exe", "/c", "exit", "0"},
                        subprocess::input{subprocess::PIPE},
                        subprocess::output{subprocess::PIPE},
                        subprocess::error{subprocess::PIPE});
    p.wait();
}
```

On the master branch, it prints:
```
Detected memory leaks!
Dumping objects ->
{204} normal block at 0x0147E740, 18 bytes long.
 Data: <cmd.exe /c exit > 63 6D 64 2E 65 78 65 20 2F 63 20 65 78 69 74 20
Object dump complete.

```

With this PR, it prints nothing.
